import { useCallback, useState } from 'react';
import { useDropzone } from 'react-dropzone';
import { useAuth } from '@/context/AuthContext';
import { useToast } from '@/hooks/util/use-toast';
import { DocumentProcessingApiClient } from '@/modules/ai-content/adapters/api-client/DocumentProcessingApiClient';
import { container } from '@/infrastructure/di/container';
import { UseFormSetValue } from 'react-hook-form';

interface UseFileUploadOptions {
  onSuccess?: (fileName: string) => void;
  onError?: (error: string) => void;
  fieldName?: string;
  acceptedFormats?: {
    [key: string]: string[];
  };
}

/**
 * Custom hook for handling file uploads with document processing.
 * Handles authentication, file processing, and error handling.
 */
export function useFileUpload(
  setValue: UseFormSetValue<any>,
  options: UseFileUploadOptions = {}
) {
  const { 
    onSuccess, 
    onError, 
    fieldName = 'text',
    acceptedFormats = {
      'application/pdf': ['.pdf'],
      'text/plain': ['.txt'],
      'text/markdown': ['.md'],
    }
  } = options;

  const [isUploading, setIsUploading] = useState(false);
  const { firebaseUser, refetchUser } = useAuth();
  const { toast } = useToast();

  const onDrop = useCallback(async (acceptedFiles: File[]) => {
    const file = acceptedFiles[0];
    if (!file) return;

    if (!firebaseUser) {
      const errorMsg = "You must be logged in to process files.";
      toast({ 
        title: "Authentication Error", 
        description: errorMsg, 
        variant: "destructive" 
      });
      onError?.(errorMsg);
      return;
    }

    setIsUploading(true);
    const formData = new FormData();
    formData.append('file', file);

    try {
      const token = await firebaseUser.getIdToken();
      const client = container.resolve(DocumentProcessingApiClient);
      const result = await client.processFileApi(formData, token);

      setValue(fieldName, result.markdown, { shouldValidate: true });

      const successMsg = `Text extracted from ${file.name}.`;
      toast({ 
        title: "File Processed", 
        description: successMsg 
      });

      onSuccess?.(file.name);
      refetchUser();
    } catch (error: any) {
      const errorMsg = error.message || "Failed to process file";
      toast({ 
        title: "File Processing Failed", 
        description: errorMsg, 
        variant: "destructive" 
      });
      onError?.(errorMsg);
    } finally {
      setIsUploading(false);
    }
  }, [firebaseUser, setValue, fieldName, refetchUser, toast, onSuccess, onError]);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    multiple: false,
    accept: acceptedFormats,
  });

  return {
    isUploading,
    getRootProps,
    getInputProps,
    isDragActive,
  };
}
"}

{"file_path": "src/hooks/util/useCopyToClipboard.ts", "initial_content": "'use client';

import { useState, useCallback } from 'react';
import { useToast } from '@/hooks/util/use-toast';

interface UseCopyToClipboardOptions {
  successMessage?: string;
  errorMessage?: string;
  duration?: number;
}

/**
 * Custom hook for copying text to clipboard with toast notifications.
 */
export function useCopyToClipboard(options: UseCopyToClipboardOptions = {}) {
  const {
    successMessage = 'Copied to clipboard',
    errorMessage = 'Failed to copy to clipboard',
    duration = 2000,
  } = options;

  const [isCopying, setIsCopying] = useState(false);
  const { toast } = useToast();

  const copyToClipboard = useCallback(async (text: string) => {
    if (!text) {
      toast({
        title: 'Error',
        description: 'No text to copy',
        variant: 'destructive',
      });
      return false;
    }

    setIsCopying(true);
    try {
      await navigator.clipboard.writeText(text);
      toast({
        title: 'Success',
        description: successMessage,
        duration,
      });
      return true;
    } catch (error) {
      toast({
        title: 'Copy Failed',
        description: errorMessage,
        variant: 'destructive',
      });
      return false;
    } finally {
      setIsCopying(false);
    }
  }, [successMessage, errorMessage, duration, toast]);

  return {
    isCopying,
    copyToClipboard,
  };
}
"}

