import { adminDb } from "@/infrastructure/firebase/server-init";
import { DocumentData, QueryConstraint } from "firebase-admin/firestore";

/**
 * Base repository class for Firebase/Firestore operations.
 * Provides common CRUD patterns and utilities for all Firebase repositories.
 */
export abstract class BaseFirebaseRepository<T extends DocumentData> {
  protected collection = adminDb.collection(this.getCollectionName());

  /**
   * Must be implemented by subclasses to specify the collection name.
   */
  protected abstract getCollectionName(): string;

  /**
   * Adds the current timestamp to the document data.
   */
  protected addTimestamp(data: Partial<T>): Partial<T> {
    return {
      ...data,
      updatedAt: new Date().toISOString(),
    };
  }

  /**
   * Adds creation and update timestamps to new documents.
   */
  protected addTimestamps(data: Partial<T>, isNew: boolean = false): Partial<T> {
    const withUpdatedAt = this.addTimestamp(data);
    if (isNew) {
      return {
        ...withUpdatedAt,
        createdAt: new Date().toISOString(),
      };
    }
    return withUpdatedAt;
  }

  /**
   * Gets a single document by ID.
   */
  async getById(id: string): Promise<T | null> {
    if (!id) return null;
    const doc = await this.collection.doc(id).get();
    if (!doc.exists) return null;
    return { id: doc.id, ...doc.data() } as T;
  }

  /**
   * Gets multiple documents by IDs.
   */
  async getByIds(ids: string[]): Promise<T[]> {
    if (ids.length === 0) return [];
    const snapshot = await this.collection.where("id", "in", ids).get();
    return snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() } as T));
  }

  /**
   * Saves a document (creates or updates).
   */
  async save(data: T): Promise<T> {
    const id = (data as any).id || this.collection.doc().id;
    const docRef = this.collection.doc(id);
    const doc = await docRef.get();
    const isNew = !doc.exists;

    const dataToSave = {
      ...data,
      id,
      ...this.addTimestamps(data, isNew),
    };

    await docRef.set(dataToSave, { merge: true });
    return dataToSave;
  }

  /**
   * Updates a document by ID.
   */
  async update(id: string, data: Partial<T>): Promise<T> {
    const updatePayload = this.addTimestamp(data);
    await this.collection.doc(id).update(updatePayload);
    const updated = await this.getById(id);
    if (!updated) throw new Error(`Failed to refetch updated document with ID: ${id}`);
    return updated;
  }

  /**
   * Deletes a document by ID.
   */
  async delete(id: string): Promise<void> {
    await this.collection.doc(id).delete();
  }

  /**
   * Gets paginated documents with cursor-based pagination.
   */
  async getPaginated(
    options: { limit: number; lastVisibleId?: string; orderBy?: string; direction?: "asc" | "desc" },
    constraints?: QueryConstraint[]
  ) {
    const { limit, lastVisibleId, orderBy = "createdAt", direction = "desc" } = options;

    let query = this.collection.orderBy(orderBy, direction).limit(limit + 1);

    if (constraints) {
      constraints.forEach((constraint) => {
        query = query.where(constraint as any);
      });
    }

    if (lastVisibleId) {
      const lastDoc = await this.collection.doc(lastVisibleId).get();
      if (lastDoc.exists) {
        query = query.startAfter(lastDoc);
      }
    }

    const snapshot = await query.get();
    const items = snapshot.docs.slice(0, limit).map((doc) => ({ id: doc.id, ...doc.data() } as T));
    const hasNextPage = snapshot.docs.length > limit;
    const newLastVisibleId = hasNextPage ? snapshot.docs[snapshot.docs.length - 2]?.id : null;

    return { items, hasNextPage, lastVisibleId: newLastVisibleId };
  }

  /**
   * Counts documents matching the criteria.
   */
  async count(constraints?: QueryConstraint[]): Promise<number> {
    let query = this.collection;

    if (constraints) {
      constraints.forEach((constraint) => {
        query = query.where(constraint as any);
      });
    }

    const snapshot = await query.count().get();
    return snapshot.data().count;
  }

  /**
   * Deletes multiple documents by IDs.
   */
  async deleteMultiple(ids: string[]): Promise<void> {
    const batch = adminDb.batch();
    ids.forEach((id) => {
      batch.delete(this.collection.doc(id));
    });
    await batch.commit();
  }
}
